with web_events_by_session as (select session_id, sum(case when page = '/cart' then duration_sec else 0 end) as cart_duration_sec, round(avg(duration_sec), 2) as avg_duration_sec from web_events where duration_sec between 162 and 470 group by session_id) select s.started_at, webs.cart_duration_sec, webs.avg_duration_sec from sessions s inner join web_events_by_session webs on s.id = webs.session_id order by cart_duration_sec desc, avg_duration_sec desc;
